use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},process::Command};const R:&str="/home/ubuntu/src/zopro-perf-work/serial-phi175";const M:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert_eq!(read(r("native/result.json"))["status"],"complete");let mut exact=0;let mut field=0;let m=read(M);for(f,h)in m["source_files_sha256"].as_object().unwrap(){if hash(r("source").join(f))==h.as_str().unwrap(){exact+=1}else{assert_eq!(f,"crates/zopro-core/src/msm_affine/g2_phi.rs");}if f.starts_with("crates/zopro-bn254/"){assert_eq!(hash(r("source").join(f)),h.as_str().unwrap());field+=1;}}assert_eq!(exact,174);assert_eq!(field,17);
let edit=read(r("source-audit.json"));let s=fs::read_to_string(r("source").join(edit["changed_file"].as_str().unwrap())).unwrap();let back=s.replacen(edit["after"].as_str().unwrap(),edit["before"].as_str().unwrap(),1);assert_eq!(format!("{:x}",Sha256::digest(back.as_bytes())),m["source_files_sha256"][edit["changed_file"].as_str().unwrap()]);
for mode in["off","on"]{let core=read(r(format!("native/core-{mode}/tests.json")));assert_eq!(core["passed_tests"].as_array().unwrap().len(),124);assert_eq!(core["unfiltered"],true);let prover=read(r(format!("native/prover-{mode}/tests.json")));assert_eq!(prover["passed_tests"].as_array().unwrap().len(),8);assert_eq!(prover["unfiltered"],true);}
let binary=r("native/candidate-sdk");let bytes=fs::read(&binary).unwrap();let needle=b"ZOPRO_CPU_SERIAL_PHI_PROBE";assert!(bytes.windows(needle.len()).any(|w|w==needle));let o=Command::new("nm").args(["-S","--size-sort","--defined-only"]).arg(&binary).output().unwrap();assert!(o.status.success());let text=String::from_utf8(o.stdout).unwrap();let mut selected=vec![];fs::create_dir(r("codegen")).unwrap();for line in text.lines().filter(|l|l.contains("g2_phi")&&l.contains("hb_raw")){let f:Vec<_>=line.split_whitespace().collect();assert_eq!(f.len(),4);let symbol=f[3];let out=Command::new("objdump").args(["-d","-C","--no-show-raw-insn"]).arg(format!("--disassemble={symbol}")).arg(&binary).output().unwrap();assert!(out.status.success());let body=String::from_utf8(out.stdout).unwrap();assert!(body.lines().filter(|l|l.contains(":\t")).count()>20);let to=r(format!("codegen/hb_raw-{}.asm",selected.len()));fs::write(&to,body).unwrap();selected.push(json!({"nm":line,"assembly":to,"sha256":hash(&to)}));}assert!(!selected.is_empty());let v=json!({"originals":175,"exact":exact,"inverse175":true,"field_exact":field,"core_each_mode":124,"prover_each_mode":8,"SDK_sha256":hash(&binary),"selector_string_in_binary":true,"linked_hb_raw":selected,"arithmetic_binary_identity_claimed":false,"production_changed":false});fs::write(r("code-audit.json"),serde_json::to_vec_pretty(&v).unwrap()).unwrap();println!("Audit124core/8prover per mode;174exact/inverse175/17fieldexact; linked both-loop hb_raw");}
